// AsPushAcquisition returns the union data inside the Acquisition as a PushAcquisition
func (t Acquisition) AsPushAcquisition() (PushAcquisition, error) {
	var body PushAcquisition
	err := json.Unmarshal(t.union, &body)
	return body, err
}

// FromPushAcquisition overwrites any union data inside the Acquisition as the provided PushAcquisition
func (t *Acquisition) FromPushAcquisition(v PushAcquisition) error {
	b, err := json.Marshal(v)
	if err != nil {
		return err
	}
	b, err = runtime.JSONMerge(b, []byte(`{"mode":"PUSH"}`))
	t.union = b
	return err
}

// MergePushAcquisition performs a merge with any union data inside the Acquisition, using the provided PushAcquisition
func (t *Acquisition) MergePushAcquisition(v PushAcquisition) error {
	b, err := json.Marshal(v)
	if err != nil {
		return err
	}
	b, err = runtime.JSONMerge(b, []byte(`{"mode":"PUSH"}`))
	if err != nil {
		return err
	}

	merged, err := runtime.JSONMerge(t.union, b)
	t.union = merged
	return err
}

